func (r *mutationResolver) UpdateGroup(ctx context.Context, id string, input model.UpdateGroupInput) (*model.Group, error) {
	g, err := r.Store.GetGroup(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("group %q not found: %w", id, err)
	}
	nameInput, setName := input.Name.ValueOK()
	if nameInput != nil && strings.TrimSpace(*nameInput) == "" {
		nameInput = nil
	}
	if setName && g.Provider == store.GroupProviderHive && nameInput == nil {
		return nil, fmt.Errorf("group name is required")
	}
	gParams := store.UpdateGroupParams{
		ID:      id,
		Name:    nameInput,
		SetName: setName,
	}
	if icon, ok := input.Icon.ValueOK(); ok {
		gParams.SetIcon = true
		gParams.Icon = icon
	}
	if tags, ok := input.Tags.ValueOK(); ok {
		gParams.SetTags = true
		gParams.Tags = groupTagsFromModel(tags)
	}
	g, err = r.Store.UpdateGroup(ctx, gParams)
	if err != nil {
		return nil, err
	}
	members, err := r.Store.ListGroupMembers(ctx, id)
	if err != nil {
		return nil, err
	}
	return mapGroup(ctx, r.StateReader, r.Store, g, members), nil
}

// DeleteGroup is the resolver for the deleteGroup field.
func (r *mutationResolver) DeleteGroup(ctx context.Context, id string) (bool, error) {
	if _, err := requireHiveGroup(ctx, r.Store, id); err != nil {
		return false, err
	}
	err := r.Store.DeleteGroup(ctx, id)
	if err != nil {
		return false, err
	}
	r.publishGroupMembershipChanged()
	r.publishRoomMembershipChanged()
	return true, nil
}

// AddGroupMember is the resolver for the addGroupMember field.
func (r *mutationResolver) AddGroupMember(ctx context.Context, input model.AddGroupMemberInput) (*model.Group, error) {
	if _, err := requireHiveGroup(ctx, r.Store, input.GroupID); err != nil {
		return nil, err
	}
	memberType := device.GroupMemberType(input.MemberType)
	if memberType != device.GroupMemberDevice && memberType != device.GroupMemberGroup && memberType != device.GroupMemberRoom {
		return nil, fmt.Errorf("invalid member type %q: must be %q, %q, or %q", input.MemberType, device.GroupMemberDevice, device.GroupMemberGroup, device.GroupMemberRoom)
	}

	parent := entityRef{kind: "group", id: input.GroupID}
	switch memberType {
	case device.GroupMemberGroup:
		if err := r.checkCircularDependency(ctx, parent, entityRef{kind: "group", id: input.MemberID}); err != nil {
			return nil, err
		}
	case device.GroupMemberRoom:
		if err := r.checkCircularDependency(ctx, parent, entityRef{kind: "room", id: input.MemberID}); err != nil {
			return nil, err
		}
	}

	memberID := uuid.New().String()
	if _, err := r.Store.AddGroupMember(ctx, store.AddGroupMemberParams{
		ID:         memberID,
		GroupID:    input.GroupID,
		MemberType: memberType,
		MemberID:   input.MemberID,
	}); err != nil {
		return nil, err
	}
	r.publishGroupMembershipChanged()
	return r.loadGroup(ctx, input.GroupID)
}

// RemoveGroupMember is the resolver for the removeGroupMember field.
func (r *mutationResolver) RemoveGroupMember(ctx context.Context, id string) (*model.Group, error) {
	groupID, err := r.Store.GetGroupMemberGroupID(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("group member %q not found: %w", id, err)
	}
	if _, err := requireHiveGroup(ctx, r.Store, groupID); err != nil {
		return nil, err
	}
	if err := r.Store.RemoveGroupMember(ctx, id); err != nil {
		return nil, err
	}
	r.publishGroupMembershipChanged()
	return r.loadGroup(ctx, groupID)
}

