// UpdateSetting is the resolver for the updateSetting field. Server-internal
// keys (auth.IsInternalSettingKey) are rejected so a caller cannot overwrite
// secrets that the public settings surface intentionally hides — see the doc
// comment on IsInternalSettingKey.
func (r *mutationResolver) UpdateSetting(ctx context.Context, key string, value string) (*model.Setting, error) {
	if auth.IsInternalSettingKey(key) {
		return nil, fmt.Errorf("setting %q is read-only", key)
	}
	if key == "i18n.default_content_language" && value != "en" && value != "sv" && value != "ru" {
		return nil, fmt.Errorf("unsupported content language")
	}
	if key == "i18n.translate_standard_room_names" && value != "true" && value != "false" {
		return nil, fmt.Errorf("standard room-name translation must be true or false")
	}
	if err := r.Store.UpsertSetting(ctx, key, value); err != nil {
		return nil, err
	}

	if key == "log_level" {
		if lvl, ok := logging.ParseLevel(value); ok {
			r.LevelVar.Set(lvl)
		}
	}

	return &model.Setting{Key: key, Value: value}, nil
}

// Login is the resolver for the login field. Every attempt passes through the
// per-(ip, username) LoginLimiter before any DB or password-verification work.
// This defeats alias-batched brute force where one HTTP request packs many
// login mutations. The no-such-user branch verifies a dummy credential so
// request duration cannot reveal whether a username exists.
func (r *mutationResolver) Login(ctx context.Context, input model.LoginInput) (*model.AuthPayload, error) {
	ip := auth.ClientIPFromContext(ctx)
	username := strings.TrimSpace(input.Username)
	now := time.Now()

	if r.LoginLimiter != nil {
		if ok, retry := r.LoginLimiter.Allow(ip, username, now); !ok {
			return nil, fmt.Errorf("too many login attempts; try again in %s", retry.Round(time.Second))
		}
	}

	startedAt := time.Now()
	hashAlgorithm := auth.PasswordHashAlgorithm(auth.DummyPasswordHash)
	rehash := false
	success := false
	defer func() {
		graphLogger.DebugContext(ctx, "login completed",
			slog.Int64("duration_ms", time.Since(startedAt).Milliseconds()),
			slog.String("hash_algorithm", hashAlgorithm),
			slog.Bool("rehash", rehash),
			slog.Bool("success", success),
		)
	}()

	u, err := r.Store.GetUserByUsername(ctx, username)
	if err != nil {
		_ = auth.VerifyPassword(auth.DummyPasswordHash, input.Password)
		if r.LoginLimiter != nil {
			r.LoginLimiter.RecordFailure(ip, username, now)
		}
		return nil, fmt.Errorf("invalid username or password")
	}
	hashAlgorithm = auth.PasswordHashAlgorithm(u.PasswordHash)
	if err := auth.VerifyPassword(u.PasswordHash, input.Password); err != nil {
		if r.LoginLimiter != nil {
			r.LoginLimiter.RecordFailure(ip, username, now)
		}
		return nil, fmt.Errorf("invalid username or password")
	}
	if auth.PasswordNeedsRehash(u.PasswordHash) {
		rehash = true
		upgradedHash, err := auth.HashPassword(input.Password)
		if err != nil {
			graphLogger.ErrorContext(ctx, "login password rehash failed",
				slog.String("user_id", u.ID),
				slog.String("error", err.Error()),
			)
			if r.LoginLimiter != nil {
				r.LoginLimiter.RecordFailure(ip, username, now)
			}
			return nil, fmt.Errorf("upgrade password hash: %w", err)
		}
		if err := r.Store.UpdateUserPasswordHash(ctx, u.ID, upgradedHash); err != nil {
			graphLogger.ErrorContext(ctx, "login password rehash failed",
				slog.String("user_id", u.ID),
				slog.String("error", err.Error()),
			)
			if r.LoginLimiter != nil {
				r.LoginLimiter.RecordFailure(ip, username, now)
			}
			return nil, fmt.Errorf("upgrade password hash: %w", err)
		}
		u.PasswordHash = upgradedHash
	}
	payload, err := signAuthPayload(r.Auth, u)
	if err != nil {
		if r.LoginLimiter != nil {
			r.LoginLimiter.RecordFailure(ip, username, now)
		}
		return nil, err
	}
	if r.LoginLimiter != nil {
		r.LoginLimiter.RecordSuccess(ip, username)
	}
	success = true
	return payload, nil
}

// CreateInitialUser is the resolver for the createInitialUser field. It is
// allowed only when the users table is empty and the caller presents the
// bootstrap token that was generated on first boot. Without the token the
// public createInitialUser endpoint would be a first-stranger-to-the-URL
// land-grab on any internet-exposed deploy.
func (r *mutationResolver) CreateInitialUser(ctx context.Context, input model.CreateInitialUserInput) (*model.AuthPayload, error) {
	count, err := r.Store.CountUsers(ctx)
	if err != nil {
		return nil, err
	}
	if count > 0 {
		return nil, fmt.Errorf("initial user already exists")
	}
	if r.BootstrapToken == nil {
		return nil, fmt.Errorf("bootstrap token store unavailable")
	}
	expected, err := r.BootstrapToken.Read()
	if err != nil {
		return nil, fmt.Errorf("bootstrap token unavailable")
	}
	if subtle.ConstantTimeCompare([]byte(input.BootstrapToken), []byte(expected)) != 1 {
		return nil, fmt.Errorf("invalid bootstrap token")
	}
	u, err := createUserRow(ctx, r.Store, input.Username, input.Name, input.Password, false)
	if err != nil {
		return nil, err
	}
	if err := r.BootstrapToken.ConsumeAndDelete(); err != nil {
		graphLogger.Warn("failed to delete consumed bootstrap token", "error", err)
	}
	return signAuthPayload(r.Auth, u)
}

// CreateUser is the resolver for the createUser field. Requires an
// authenticated caller. All authenticated users are currently full admins;
// roles will come later. Admin-created users are always required to change
// their initial password on first login (the admin-supplied password is
// treated as temporary).
func (r *mutationResolver) CreateUser(ctx context.Context, input model.CreateUserInput) (*model.User, error) {
	if _, ok := auth.PrincipalFromContext(ctx); !ok {
		return nil, fmt.Errorf("authentication required")
	}
	u, err := createUserRow(ctx, r.Store, input.Username, input.Name, input.Password, true)
	if err != nil {
		return nil, err
	}
	return mapUser(u), nil
}

// GuestLogin is the resolver for the guestLogin field.
func (r *mutationResolver) GuestLogin(ctx context.Context, name string) (*model.GuestAuthPayload, error) {
	ip := auth.ClientIPFromContext(ctx)
	normalized := normalizeGuestName(name)
	now := time.Now().UTC()
	limiterKey := "guest:" + normalized
	if r.LoginLimiter != nil {
		if ok, retry := r.LoginLimiter.Allow(ip, limiterKey, now); !ok {
			return nil, fmt.Errorf("too many login attempts; try again in %s", retry.Round(time.Second))
		}
	}
	guest, err := r.Store.GetActiveGuestByNormalizedName(ctx, normalized, now)
	if err != nil || normalized == "" {
		if r.LoginLimiter != nil {
			r.LoginLimiter.RecordFailure(ip, limiterKey, now)
		}
		return nil, fmt.Errorf("guest access is unavailable")
	}
	token, err := r.Auth.SignGuest(guest.ID, guest.Name, guest.CreatedAt.Add(auth.MaxGuestLifetime))
	if err != nil {
		if r.LoginLimiter != nil {
			r.LoginLimiter.RecordFailure(ip, limiterKey, now)
		}
		return nil, fmt.Errorf("sign guest token: %w", err)
	}
	if r.LoginLimiter != nil {
		r.LoginLimiter.RecordSuccess(ip, limiterKey)
	}
	return &model.GuestAuthPayload{Token: token, Guest: mapGuest(guest)}, nil
}

// CreateGuest is the resolver for the createGuest field.
func (r *mutationResolver) CreateGuest(ctx context.Context, input model.CreateGuestInput) (*model.Guest, error) {
	name := strings.TrimSpace(input.Name)
	if name == "" {
		return nil, fmt.Errorf("guest name is required")
	}
	duration, err := guestDuration(input.DurationMinutes)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	guest, err := r.Store.CreateGuest(ctx, store.CreateGuestParams{
		ID:             uuid.New().String(),
		Name:           name,
		NormalizedName: normalizeGuestName(name),
		ExpiresAt:      now.Add(duration),
		CreatedAt:      now,
	})
	if err != nil {
		if strings.Contains(strings.ToLower(err.Error()), "unique") {
			return nil, fmt.Errorf("an active guest already uses that name")
		}
		return nil, err
	}
	r.publishGuestChange(eventbus.GuestCreated, guest)
	return mapGuest(guest), nil
}

// ExtendGuest is the resolver for the extendGuest field.
func (r *mutationResolver) ExtendGuest(ctx context.Context, id string, durationMinutes int) (*model.Guest, error) {
	duration, err := guestDuration(durationMinutes)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	guest, err := r.Store.GetActiveGuestByID(ctx, id, now)
	if err != nil {
		return nil, fmt.Errorf("active guest not found")
	}
	expiresAt := guest.ExpiresAt.Add(duration)
	if expiresAt.After(guest.CreatedAt.Add(auth.MaxGuestLifetime)) {
		return nil, fmt.Errorf("guest access cannot extend beyond seven days from creation")
	}
	guest, err = r.Store.UpdateGuestExpiresAt(ctx, id, expiresAt)
	if err != nil {
		return nil, err
	}
	r.publishGuestChange(eventbus.GuestExtended, guest)
	return mapGuest(guest), nil
}

// DeleteGuest is the resolver for the deleteGuest field.
func (r *mutationResolver) DeleteGuest(ctx context.Context, id string) (bool, error) {
	guest, err := r.Store.GetGuestByID(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	deleted, err := r.Store.DeleteGuest(ctx, id)
	if err != nil || !deleted {
		return deleted, err
	}
	r.publishGuestChange(eventbus.GuestRevoked, guest)
	return true, nil
}

// BatchDeleteGuests is the resolver for the batchDeleteGuests field.
func (r *mutationResolver) BatchDeleteGuests(ctx context.Context, ids []string) (int, error) {
	active, err := r.Store.ListActiveGuests(ctx, time.Now().UTC())
	if err != nil {
		return 0, err
	}
	byID := make(map[string]store.Guest, len(active))
	for _, guest := range active {
		byID[guest.ID] = guest
	}
	deleted, err := r.Store.BatchDeleteGuests(ctx, ids)
	if err != nil {
		return 0, err
	}
	for _, id := range deleted {
		guest := byID[id]
		guest.ID = id
		r.publishGuestChange(eventbus.GuestRevoked, guest)
	}
	return len(deleted), nil
}

// UpdateCurrentUser applies a partial update to the authenticated user's
// profile. Currently covers display name and theme; avatar changes go through
// the POST /api/avatars upload endpoint.
func (r *mutationResolver) UpdateCurrentUser(ctx context.Context, input model.UpdateCurrentUserInput) (*model.User, error) {
	cu, ok := auth.PrincipalFromContext(ctx)
	if !ok {
		return nil, fmt.Errorf("authentication required")
	}
	params := store.UpdateUserProfileParams{ID: cu.ID}
	if namePtr, ok := input.Name.ValueOK(); ok && namePtr != nil {
		trimmed := strings.TrimSpace(*namePtr)
		if trimmed == "" {
			return nil, fmt.Errorf("name must not be empty")
		}
		params.Name = &trimmed
	}
	if themePtr, ok := input.Theme.ValueOK(); ok && themePtr != nil {
		s := themeToStore(*themePtr)
		params.Theme = &s
	}
	if tfPtr, ok := input.TimeFormat.ValueOK(); ok && tfPtr != nil {
		s := timeFormatToStore(*tfPtr)
		params.TimeFormat = &s
	}
	if tuPtr, ok := input.TemperatureUnit.ValueOK(); ok && tuPtr != nil {
		s := temperatureUnitToStore(*tuPtr)
		params.TemperatureUnit = &s
	}
	if hapticsPtr, ok := input.HapticsEnabled.ValueOK(); ok && hapticsPtr != nil {
		params.HapticsEnabled = hapticsPtr
	}
	if languagePtr, ok := input.Language.ValueOK(); ok && languagePtr != nil {
		s := languageToStore(*languagePtr)
		params.Language = &s
	}
	u, err := r.Store.UpdateUserProfile(ctx, params)
	if err != nil {
		return nil, err
	}
	return mapUser(u), nil
}

// ChangePassword replaces the authenticated user's password after verifying
// their existing one. The current JWT continues to work until it expires;
// server-side revocation of live tokens is out of scope.
func (r *mutationResolver) ChangePassword(ctx context.Context, input model.ChangePasswordInput) (bool, error) {
	cu, ok := auth.PrincipalFromContext(ctx)
	if !ok {
		return false, fmt.Errorf("authentication required")
	}
	if err := validatePassword(input.NewPassword); err != nil {
		return false, err
	}
	u, err := r.Store.GetUserByID(ctx, cu.ID)
	if err != nil {
		return false, fmt.Errorf("load current user: %w", err)
	}
	if err := auth.VerifyPassword(u.PasswordHash, input.OldPassword); err != nil {
		return false, fmt.Errorf("old password is incorrect")
	}
	hash, err := auth.HashPassword(input.NewPassword)
	if err != nil {
		return false, fmt.Errorf("hash password: %w", err)
	}
	if err := r.Store.UpdateUserPasswordHash(ctx, cu.ID, hash); err != nil {
		return false, err
	}
	if err := r.Store.BumpUserTokenVersion(ctx, cu.ID); err != nil {
		return false, fmt.Errorf("invalidate prior sessions: %w", err)
	}
	return true, nil
}

// CompleteFirstPasswordChange sets a fresh password hash and clears the
// must_change_password flag for the authenticated user. Returns false if the
// caller was not in the forced-change state (no row updated).
func (r *mutationResolver) CompleteFirstPasswordChange(ctx context.Context, newPassword string) (bool, error) {
	cu, ok := auth.PrincipalFromContext(ctx)
	if !ok {
		return false, fmt.Errorf("authentication required")
	}
	if err := validatePassword(newPassword); err != nil {
		return false, err
	}
	hash, err := auth.HashPassword(newPassword)
	if err != nil {
		return false, fmt.Errorf("hash password: %w", err)
	}
	n, err := r.Store.CompleteFirstPasswordChange(ctx, cu.ID, hash)
	if err != nil {
		return false, err
	}
	if n > 0 {
		if err := r.Store.BumpUserTokenVersion(ctx, cu.ID); err != nil {
			return false, fmt.Errorf("invalidate prior sessions: %w", err)
		}
	}
	return n > 0, nil
}

// ResetUserPassword sets a new password for an arbitrary user, without
// requiring the old one. Every authenticated user is a full admin today
// (roles/permissions are a future patch), so any caller can reset any target.
// Re-arms must_change_password so the target is forced through the
// forced-change flow on their next login: an admin-set password is always a
// temporary password.
func (r *mutationResolver) ResetUserPassword(ctx context.Context, id string, newPassword string) (bool, error) {
	if _, ok := auth.PrincipalFromContext(ctx); !ok {
		return false, fmt.Errorf("authentication required")
	}
	if err := validatePassword(newPassword); err != nil {
		return false, err
	}
	if _, err := r.Store.GetUserByID(ctx, id); err != nil {
		return false, fmt.Errorf("load target user: %w", err)
	}
	hash, err := auth.HashPassword(newPassword)
	if err != nil {
		return false, fmt.Errorf("hash password: %w", err)
	}
	if err := r.Store.UpdateUserPasswordHash(ctx, id, hash); err != nil {
		return false, err
	}
	if err := r.Store.SetUserMustChangePassword(ctx, id, true); err != nil {
		return false, err
	}
	if err := r.Store.BumpUserTokenVersion(ctx, id); err != nil {
		return false, fmt.Errorf("invalidate prior sessions: %w", err)
	}
	return true, nil
}

// ForceLogoutAllSessions bumps a user's token_version so every previously
// issued JWT for them is rejected by the auth middleware. When userID is nil
// the caller's own tokens are invalidated. With roles still pending, any
// authenticated caller can force-logout any user — matching the project's
// "all auth = admin" posture; revisit when role gating lands.
func (r *mutationResolver) ForceLogoutAllSessions(ctx context.Context, userID *string) (bool, error) {
	cu, ok := auth.PrincipalFromContext(ctx)
	if !ok {
		return false, fmt.Errorf("authentication required")
	}
	target := cu.ID
	if userID != nil && *userID != "" {
		if _, err := r.Store.GetUserByID(ctx, *userID); err != nil {
			return false, fmt.Errorf("load target user: %w", err)
		}
		target = *userID
	}
	if err := r.Store.BumpUserTokenVersion(ctx, target); err != nil {
		return false, err
	}
	return true, nil
}

// DeleteUser removes a user. Rejects self-delete so the acting admin can't
// lock themselves out. The row's avatar file (if any) is deleted best-effort.
// Creator attribution on scenes/automations/groups/rooms becomes NULL via the
// FK ON DELETE SET NULL configured on those tables.
func (r *mutationResolver) DeleteUser(ctx context.Context, id string) (bool, error) {
	cu, ok := auth.PrincipalFromContext(ctx)
	if !ok {
		return false, fmt.Errorf("authentication required")
	}
	if cu.ID == id {
		return false, fmt.Errorf("you cannot delete yourself")
	}
	avatar, err := r.Store.GetUserAvatarPath(ctx, id)
	if err != nil {
		return false, fmt.Errorf("load target user: %w", err)
	}
	if err := r.Store.DeleteUser(ctx, id); err != nil {
		return false, err
	}
	if avatar != nil && *avatar != "" && r.AvatarDir != "" {
		full := filepath.Join(r.AvatarDir, *avatar)
		if rmErr := os.Remove(full); rmErr != nil && !errors.Is(rmErr, os.ErrNotExist) {
			graphLogger.Warn("failed to remove avatar file on user delete", "path", full, "error", rmErr)
		}
	}
	return true, nil
}

