// NativeEffectOptions is the resolver for the nativeEffectOptions field.
func (r *queryResolver) NativeEffectOptions(ctx context.Context) ([]*model.NativeEffectOption, error) {
	terminators := make(map[string]struct{}, len(nativeEffectTerminators))
	for _, t := range nativeEffectTerminators {
		terminators[t] = struct{}{}
	}

	type statusCounts struct {
		confirmed   int
		untested    int
		unsupported int
	}
	counts := make(map[string]statusCounts)
	for _, d := range r.StateReader.ListDevices() {
		if d.RuntimeDisabled() || d.Removed {
			continue
		}
		for _, c := range d.Capabilities {
			if c.Name != device.CapEffect || !c.CanSet() {
				continue
			}
			seenInDevice := make(map[string]struct{}, len(c.Values))
			for _, v := range c.Values {
				if _, ok := terminators[v]; ok {
					continue
				}
				if _, dup := seenInDevice[v]; dup {
					continue
				}
				seenInDevice[v] = struct{}{}
				status, err := r.nativeEffectStatus(ctx, d, v)
				if err != nil {
					return nil, err
				}
				count := counts[v]
				switch status {
				case device.NativeEffectSupportConfirmed:
					count.confirmed++
				case device.NativeEffectSupportUnsupported:
					count.unsupported++
				default:
					count.untested++
				}
				counts[v] = count
			}
		}
	}

	out := make([]*model.NativeEffectOption, 0, len(counts))
	for name, count := range counts {
		out = append(out, &model.NativeEffectOption{
			Name:                   name,
			DisplayName:            sentenceCase(name),
			Source:                 string(device.SourceZigbee2MQTT),
			ConfirmedDeviceCount:   count.confirmed,
			UntestedDeviceCount:    count.untested,
			UnsupportedDeviceCount: count.unsupported,
		})
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	return out, nil
}

// NativeEffectSupport is the resolver for the nativeEffectSupport field.
func (r *queryResolver) NativeEffectSupport(ctx context.Context, name string) ([]*model.NativeEffectDeviceSupport, error) {
	if strings.TrimSpace(name) == "" {
		return nil, errors.New("name must not be empty")
	}
	out := make([]*model.NativeEffectDeviceSupport, 0)
	for _, dev := range r.StateReader.ListDevices() {
		if dev.RuntimeDisabled() || dev.Removed || !deviceAdvertisesNativeEffect(dev, name) {
			continue
		}
		status, err := r.nativeEffectStatus(ctx, dev, name)
		if err != nil {
			return nil, err
		}
		out = append(out, &model.NativeEffectDeviceSupport{
			DeviceID: string(dev.ID), Status: nativeEffectSupportStatusToModel(status),
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].DeviceID < out[j].DeviceID })
	return out, nil
}

// DeviceStateChanged is the resolver for the deviceStateChanged field.
func (r *subscriptionResolver) DeviceStateChanged(ctx context.Context, deviceID *string) (<-chan *model.DeviceStateEvent, error) {
	ch := r.EventBus.Subscribe(eventbus.EventDeviceStateChanged)
	out := make(chan *model.DeviceStateEvent, 1)

	go func() {
		defer close(out)
		defer r.EventBus.Unsubscribe(ch)

		for {
			select {
			case <-ctx.Done():
				return
			case evt, ok := <-ch:
				if !ok {
					return
				}
				if deviceID != nil && evt.DeviceID != *deviceID {
					continue
				}
				state := resolveDeviceStateFromReader(r.StateReader, device.DeviceID(evt.DeviceID))
				if state == nil {
					continue
				}
				if change, ok := evt.Payload.(device.DeviceStateChange); ok {
					state.Transition = change.State.Transition
				}
				select {
				case out <- &model.DeviceStateEvent{
					DeviceID: evt.DeviceID,
					State:    state,
				}:
				case <-ctx.Done():
					return
				}
			}
		}
	}()

	return out, nil
}

