// GroupsChanged is the resolver for the groupsChanged field.
func (r *subscriptionResolver) GroupsChanged(ctx context.Context) (<-chan []string, error) {
	ch := r.EventBus.Subscribe(eventbus.EventGroupSynced)
	out := make(chan []string, 1)
	go func() {
		defer close(out)
		defer r.EventBus.Unsubscribe(ch)
		pending := make(map[string]struct{})
		var timer *time.Timer
		var timerCh <-chan time.Time
		flush := func() {
			if len(pending) == 0 {
				return
			}
			ids := make([]string, 0, len(pending))
			for id := range pending {
				ids = append(ids, id)
			}
			sort.Strings(ids)
			pending = make(map[string]struct{})
			select {
			case out <- ids:
			default:
				select {
				case <-out:
				default:
				}
				out <- ids
			}
		}
		for {
			select {
			case <-ctx.Done():
				if timer != nil {
					timer.Stop()
				}
				return
			case evt, ok := <-ch:
				if !ok {
					return
				}
				payload, ok := evt.Payload.(eventbus.GroupSyncedEvent)
				if !ok {
					continue
				}
				for _, id := range payload.ChangedIDs {
					if len(pending) < 256 {
						pending[id] = struct{}{}
					}
				}
				if timer == nil {
					timer = time.NewTimer(25 * time.Millisecond)
					timerCh = timer.C
				}
			case <-timerCh:
				flush()
				timer = nil
				timerCh = nil
			}
		}
	}()
	return out, nil
}

