// GuestChanged is the resolver for the guestChanged field.
func (r *subscriptionResolver) GuestChanged(ctx context.Context) (<-chan *model.GuestChangeEvent, error) {
	principal, _ := auth.PrincipalFromContext(ctx)
	changes := r.EventBus.Subscribe(eventbus.EventGuestChanged)
	out := make(chan *model.GuestChangeEvent, 1)
	go func() {
		defer close(out)
		defer r.EventBus.Unsubscribe(changes)
		for {
			select {
			case <-ctx.Done():
				return
			case event, ok := <-changes:
				if !ok {
					return
				}
				change, ok := event.Payload.(eventbus.GuestChangedEvent)
				if !ok || principal.Guest && change.GuestID != principal.ID {
					continue
				}
				mapped := &model.GuestChangeEvent{
					GuestID: change.GuestID,
					Kind:    mapGuestChangeKind(change.Kind),
				}
				if change.Kind == eventbus.GuestCreated || change.Kind == eventbus.GuestExtended {
					mapped.Guest = mapGuest(store.Guest{
						ID:        change.GuestID,
						Name:      change.Name,
						ExpiresAt: change.ExpiresAt,
						CreatedAt: change.CreatedAt,
					})
				}
				select {
				case out <- mapped:
				case <-ctx.Done():
					return
				}
			}
		}
	}()
	return out, nil
}

// LogStream is the resolver for the logStream field.
func (r *subscriptionResolver) LogStream(ctx context.Context) (<-chan *model.LogEntry, error) {
	ch, unsub := r.LogBuffer.Subscribe()
	out := make(chan *model.LogEntry, 1)

	go func() {
		defer close(out)
		defer unsub()

		for {
			select {
			case <-ctx.Done():
				return
			case e, ok := <-ch:
				if !ok {
					return
				}
				select {
				case out <- mapLogEntry(e):
				case <-ctx.Done():
					return
				}
			}
		}
	}()

	return out, nil
}

// ActivityStream is the resolver for the activityStream field.
func (r *subscriptionResolver) ActivityStream(ctx context.Context, advanced *bool) (<-chan *model.ActivityEvent, error) {
	showAdvanced := advanced != nil && *advanced

	ch, unsub := r.ActivityBuffer.Subscribe()
	out := make(chan *model.ActivityEvent, 16)

	go func() {
		defer close(out)
		defer unsub()

		for {
			select {
			case <-ctx.Done():
				return
			case row, ok := <-ch:
				if !ok {
					return
				}
				if !showAdvanced && (row.Type == "command.requested" || row.Type == "automation.node_activated") {
					continue
				}
				select {
				case out <- mapActivityEvent(row):
				case <-ctx.Done():
					return
				}
			}
		}
	}()

	return out, nil
}

